from pathlib import Path
from typing import Literal

from pydantic_settings import BaseSettings, SettingsConfigDict

_BASE_DIR = Path(__file__).parent.parent

class Settings(BaseSettings):
    # DeepSeek
    deepseek_api_key: str = ""
    deepseek_base_url: str = "https://api.deepseek.com"
    deepseek_model: str = "deepseek-v4-flash"
    deepseek_request_timeout: int = 60

    # Optional LLM enhancement for specialist agents.
    # Baseline plam/advice are still generated by tools and rules.
    exercise_llm_refine_enabled: bool = False
    environment_llm_advice_enabled: bool = False

    # JWT
    jwt_secret_key: str = "dev-secret-key-change-in-production"
    jwt_algorithm: str = "HS256"
    jwt_expire_hours: int = 24

    # Database
    database_url: str = "sqlite+aiosqlite:///.data/health.db"

    # Production RAG: Elasticsearch BM25 + DashScope dense vector search.
    rag_index_name: str = "ai_health_knowledge"
    rag_top_k: int = 5
    rag_candidate_k: int = 20
    rag_seed_on_empty: bool = False
    rag_embedding_model: str = "text-embedding-v4"
    rag_embedding_batch_size: int = 10
    dashscope_api_key: str = ""
    dashscope_base_url: str = "https://dashscope.aliyuncs.com/compatible-mode/v1"
    dashscope_embedding_model: str = "text-embedding-v4"
    dashscope_embedding_dimension: int = 1024
    dashscope_request_timeout: int = 60
    rag_vector_weight: float = 0.65
    rag_bm25_weight: float = 0.35
    rag_use_reranker: bool = False
    rag_reranker_model: str = "bge-reranker-base"
    rag_warmup_on_startup: bool = False
    memory_index_name: str = "ai_health_long_term_memory"
    memory_top_k: int = 6
    memory_candidate_k: int = 16
    memory_vector_weight: float = 0.7
    memory_bm25_weight: float = 0.3
    memory_max_days: int = 365
    memory_write_enabled: bool = True
    memory_use_llm_supplement: bool = True
    elasticsearch_url: str | None = None
    elasticsearch_username: str | None = None
    elasticsearch_password: str | None = None
    elasticsearch_api_key: str | None = None

    # Redis
    redis_host: str = "localhost"
    redis_port: int = 6379
    redis_db: int = 0
    redis_password: str | None = None

    # Short-term memory
    short_term_backend: Literal["memory", "redis"] = "redis"
    short_term_max_messages: int = 20
    short_term_ttl_seconds: int = 259200
    short_term_key_prefix: str = "ai_health:short_term:v1"
    short_term_redis_socket_timeout: float = 2.0
    short_term_redis_connect_timeout: float = 2.0

    # Medium-term memory
    medium_term_enabled: bool = True
    medium_term_recent_window: int = 8
    medium_term_trigger_new_messages: int = 4
    medium_term_max_chars: int = 500

    # Rate limiting
    rate_limit_enabled: bool = True
    rate_limit_general: int = 100
    rate_limit_window_minutes: int = 15
    rate_limit_llm: int = 20
    rate_limit_llm_window_minutes: int = 60
    max_request_body_bytes: int = 5 * 1024 * 1024
    max_upload_body_bytes: int = 50 * 1024 * 1024
    max_knowledge_pdf_bytes: int = 30 * 1024 * 1024

    model_config = SettingsConfigDict(env_file=str(_BASE_DIR/".env"), env_file_encoding="utf-8")

settings = Settings()
